// أيقونات مأخوذة من صور المرجع (مُتتبَّعة إلى SVG) — نفس شكل الأيقونات في التصاميم
function mk(w, h, p, flip) {
  return function Icon({ size = 20, className, style, ...rest }) {
    return (
      <svg width={size} height={size} viewBox={`0 0 ${w} ${h}`} fill="currentColor" className={className} style={flip ? { transform: 'scaleX(-1)', ...style } : style} aria-hidden="true" {...rest}>
        <path d={p} fillRule="evenodd" />
      </svg>
    );
  };
}
